const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const bryceCanyon = ee.Geometry.Point([-112.1871, 37.5930]); // Bryce Canyon National Park
    const lasVegas = ee.Geometry.Point([-115.1398, 36.1699]); // Las Vegas
    const startDate = '2024-01-01';
    const endDate = '2024-07-01'; // Use a recent range to get latest available data

    // 2. Data Acquisition
    const collection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
        .filterDate(startDate, endDate)
        .select('avg_rad');

    // Check if the collection is empty
    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
        console.log(`No VIIRS DNB images found for the period: ${startDate} to ${endDate}.`);
        console.log('A: Yes');
        return;
    }
    console.log(`Found ${collectionSize} monthly images for 2024.`);

    // 3. Processing: Create a mean composite over the period
    const image = collection.mean();

    // 4. Calculation: Extract light intensity values for both locations
    // Use a larger scale as VIIRS DNB resolution is ~750m. 1000m is safe.
    const bryceParams = {
        reducer: ee.Reducer.mean(),
        geometry: bryceCanyon,
        scale: 1000,
        maxPixels: 1e9
    };
    const vegasParams = {
        reducer: ee.Reducer.mean(),
        geometry: lasVegas,
        scale: 1000,
        maxPixels: 1e9
    };

    const bryceLightDict = image.reduceRegion(bryceParams);
    const vegasLightDict = image.reduceRegion(vegasParams);

    // Use evaluate to fetch results asynchronously and avoid blocking
    const results = await new Promise((resolve, reject) => {
        ee.Dictionary({
            'bryce': bryceLightDict.get('avg_rad'),
            'vegas': vegasLightDict.get('avg_rad')
        }).evaluate((data, error) => {
            if (error) reject(error);
            else resolve(data);
        });
    });

    const bryceLight = results.bryce;
    const vegasLight = results.vegas;

    // 5. Validation & Final Answer
    if (bryceLight === null || vegasLight === null) {
        console.log('Could not extract valid pixel values for one or both locations.');
        if (bryceLight === null) console.log('Bryce Canyon has no valid pixels.');
        if (vegasLight === null) console.log('Las Vegas has no valid pixels.');
        console.log('C2');
        return;
    }

    console.log(`Bryce Canyon Avg Radiance: ${bryceLight.toFixed(2)} nW/cm^2/sr`);
    console.log(`Las Vegas Avg Radiance: ${vegasLight.toFixed(2)} nW/cm^2/sr`);

    if (bryceLight < vegasLight) {
        console.log('Nighttime light intensity in Bryce Canyon is lower than in Las Vegas.');
        console.log('A');
    } else {
        console.log('Nighttime light intensity in Bryce Canyon is not lower than in Las Vegas.');
        console.log('B');
    }
}

